mockup.css:
.mock-section-wordmark-band { background: #a8340f; color: #fdf3e4;
  font-family: "Helvetica Neue", Inter, ui-sans-serif, sans-serif;
  display: flex; flex-direction: column; justify-content: center; gap: 2.2cqw; padding: 0 4cqw; }
.mock-section-wordmark-band .phrase { font-weight: 800; font-size: 12.4cqw; line-height: .86;
  letter-spacing: -.045em; text-transform: uppercase; white-space: nowrap; }
.mock-section-wordmark-band .under { display: flex; justify-content: space-between;
  font-size: 1.25cqw; letter-spacing: .18em; text-transform: uppercase; opacity: .7; }
